const products = [
  {
    productId: 3743800,
    productUrl: 'https://www.power.no/data-og-tilbehoer/stasjonaer-pc/apple-mac-mini-m4-16-gb-256-gb/p-3743800/',
    label: 'Mac Mini M4 16/256'
  },
  {
    productId: 3743802,
    productUrl: 'https://www.power.no/data-og-tilbehoer/stasjonaer-pc/apple-mac-mini-m4-24-gb-512-gb/p-3743802/',
    label: 'Mac Mini M4 24/512'
  }
];

const watchedStoreIds = [1123, 1186, 1134, 1121, 1115, 1130, 1120, 1116, 1118, 1122, 1119];
const postalCode = '0369';

const results = [];

for (const product of products) {
  try {
    const response = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://fyrk-agent-runtime.fly.dev/run/stock-monitor',
      headers: { 'Content-Type': 'application/json' },
      body: {
        version: '0.1',
        input: {
          productId: product.productId,
          productUrl: product.productUrl,
          postalCode: postalCode,
          watchedStoreIds: watchedStoreIds
        },
        dryRun: false,
        publish: true
      },
      json: true,
      timeout: 30000
    });

    results.push({
      product: product.label,
      status: response.status,
      webStock: response.output?.webStockStatus,
      storesWithStock: response.output?.storesWithStock?.length ?? 0,
      notificationSent: response.output?.notificationSent ?? false
    });
  } catch (err) {
    results.push({
      product: product.label,
      status: 'error',
      error: err.message
    });
  }
}

return [{ json: { results } }];
